class Solution {
    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
        String[] sorted = java.util.Arrays.copyOf(words, words.length);
        java.util.Arrays.sort(sorted, java.util.Comparator.comparingInt(String::length));
        java.util.Set<String> dictionary = new java.util.HashSet<>();
        java.util.Set<String> concatenated = new java.util.HashSet<>();
        for (String word : sorted) {
            if (canFormWithShorterWords(word, dictionary)) {
                concatenated.add(word);
            }
            dictionary.add(word);
        }
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String word : words) {
            if (concatenated.contains(word)) {
                result.add(word);
            }
        }
        return result;
    }

    private boolean canFormWithShorterWords(String word, java.util.Set<String> dictionary) {
        if (dictionary.isEmpty()) {
            return false;
        }
        int n = word.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int end = 1; end <= n; end++) {
            for (int start = 0; start < end; start++) {
                if (dp[start] && dictionary.contains(word.substring(start, end))) {
                    dp[end] = true;
                    break;
                }
            }
        }
        return dp[n];
    }
}

class Solution {
    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
        java.util.Set<String> dictionary = new java.util.HashSet<>(java.util.Arrays.asList(words));
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String word : words) {
            Boolean[][] memo = new Boolean[word.length() + 1][3];
            if (canBuild(word, 0, 0, dictionary, memo)) {
                result.add(word);
            }
        }
        return result;
    }

    private boolean canBuild(String word, int index, int pieces,
                             java.util.Set<String> dictionary, Boolean[][] memo) {
        if (index == word.length()) {
            return pieces >= 2;
        }
        int cappedPieces = Math.min(pieces, 2);
        if (memo[index][cappedPieces] != null) {
            return memo[index][cappedPieces];
        }
        for (int end = index + 1; end <= word.length(); end++) {
            if (index == 0 && end == word.length()) {
                continue;
            }
            if (dictionary.contains(word.substring(index, end))
                    && canBuild(word, end, Math.min(2, pieces + 1), dictionary, memo)) {
                memo[index][cappedPieces] = true;
                return true;
            }
        }
        memo[index][cappedPieces] = false;
        return false;
    }
}

class Solution {
    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
        TrieNode root = new TrieNode();
        for (String word : words) {
            insert(root, word);
        }
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String word : words) {
            Boolean[][] memo = new Boolean[word.length() + 1][3];
            if (dfs(root, word, 0, 0, memo)) {
                result.add(word);
            }
        }
        return result;
    }

    private boolean dfs(TrieNode root, String word, int index, int pieces, Boolean[][] memo) {
        if (index == word.length()) {
            return pieces >= 2;
        }
        int cappedPieces = Math.min(pieces, 2);
        if (memo[index][cappedPieces] != null) {
            return memo[index][cappedPieces];
        }
        TrieNode node = root;
        for (int end = index; end < word.length(); end++) {
            node = node.children[word.charAt(end) - 'a'];
            if (node == null) {
                break;
            }
            if (node.word && dfs(root, word, end + 1, Math.min(2, pieces + 1), memo)) {
                memo[index][cappedPieces] = true;
                return true;
            }
        }
        memo[index][cappedPieces] = false;
        return false;
    }

    private void insert(TrieNode root, String word) {
        TrieNode node = root;
        for (int i = 0; i < word.length(); i++) {
            int index = word.charAt(i) - 'a';
            if (node.children[index] == null) {
                node.children[index] = new TrieNode();
            }
            node = node.children[index];
        }
        node.word = true;
    }

    private static class TrieNode {
        private final TrieNode[] children = new TrieNode[26];
        private boolean word;
    }
}

class Solution {
    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
        java.util.Set<String> dictionary = new java.util.HashSet<>(java.util.Arrays.asList(words));
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String word : words) {
            if (reachableWithBfs(word, dictionary)) {
                result.add(word);
            }
        }
        return result;
    }

    private boolean reachableWithBfs(String word, java.util.Set<String> dictionary) {
        int n = word.length();
        boolean[][] seen = new boolean[n + 1][3];
        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
        queue.addLast(new int[] {0, 0});
        seen[0][0] = true;
        while (!queue.isEmpty()) {
            int[] state = queue.removeFirst();
            int start = state[0];
            int pieces = state[1];
            for (int end = start + 1; end <= n; end++) {
                if (start == 0 && end == n) {
                    continue;
                }
                if (!dictionary.contains(word.substring(start, end))) {
                    continue;
                }
                int nextPieces = Math.min(2, pieces + 1);
                if (end == n && nextPieces >= 2) {
                    return true;
                }
                if (!seen[end][nextPieces]) {
                    seen[end][nextPieces] = true;
                    queue.addLast(new int[] {end, nextPieces});
                }
            }
        }
        return false;
    }
}

class Solution {
    public java.util.List<String> findAllConcatenatedWordsInADict(String[] words) {
        java.util.Set<String> dictionary = new java.util.HashSet<>(java.util.Arrays.asList(words));
        java.util.List<String> result = new java.util.ArrayList<>();
        for (String word : words) {
            if (minimumPieces(word, dictionary) >= 2) {
                result.add(word);
            }
        }
        return result;
    }

    private int minimumPieces(String word, java.util.Set<String> dictionary) {
        int n = word.length();
        int unreachable = 1_000_000;
        int[] pieces = new int[n + 1];
        java.util.Arrays.fill(pieces, unreachable);
        pieces[0] = 0;
        for (int start = 0; start < n; start++) {
            if (pieces[start] == unreachable) {
                continue;
            }
            for (int end = start + 1; end <= n; end++) {
                if (start == 0 && end == n) {
                    continue;
                }
                if (dictionary.contains(word.substring(start, end))) {
                    pieces[end] = Math.min(pieces[end], pieces[start] + 1);
                }
            }
        }
        return pieces[n] == unreachable ? 0 : pieces[n];
    }
}
